{"compatibility":"minor","safety_note_md":"# SafeStan Safety Note

Compatibility: minor.

Protected data: `y_flat`, a deterministic row-major flattening of the original observed array `y`.

Generated files: `model_safe.stan`, `data_safe.json`.

Changes: added `y_flat` with deterministic relation `y_flat[(j - 1) * n_trials + t] = y[j, t]` for Stan indices `j = 1..n_dogs`, `t = 1..n_trials`. The original `y` remains as context for the deterministic history arrays `prev_shock` and `prev_avoid`. Moved all parameter priors before parameter-dependent likelihood computations, changed `to_vector(z) ~ normal(0, 1)` to the equivalent elementwise prior `z ~ normal(0, 1)`, and replaced the nested indexed Bernoulli observations with one vectorized protected observation statement `y_flat ~ bernoulli(p_flat)` outside loops.
","model_safe_stan":"data {
  int<lower=0> n_dogs;
  int<lower=0> n_trials;
  array[n_dogs, n_trials] int<lower=0, upper=1> y;
  array[n_dogs * n_trials] int<lower=0, upper=1> y_flat;
}
transformed data {
  int<lower=0> J = n_dogs;
  int<lower=0> T = n_trials;
  matrix<lower=0>[J, T] prev_shock;
  matrix<lower=0>[J, T] prev_avoid;
  for (j in 1 : J) {
    prev_shock[j, 1] = 0;
    prev_avoid[j, 1] = 0;
    for (t in 2 : T) {
      prev_shock[j, t] = prev_shock[j, t - 1] + y[j, t - 1];
      prev_avoid[j, t] = prev_avoid[j, t - 1] + 1 - y[j, t - 1];
    }
  }
}
parameters {
  vector[2] mu_logit_ab;
  vector<lower=0>[2] sigma_logit_ab;
  cholesky_factor_corr[2] L_logit_ab;
  matrix[J, 2] z;
}
transformed parameters {
  matrix[J, 2] logit_ab = rep_vector(1, J) * mu_logit_ab'
                          + z * diag_pre_multiply(sigma_logit_ab, L_logit_ab);
  corr_matrix[2] Omega_logit_ab = L_logit_ab * L_logit_ab';
  cov_matrix[2] Sigma_logit_ab = quad_form_diag(Omega_logit_ab,
                                                sigma_logit_ab);
  vector[J] a = inv_logit(logit_ab[ : , 1]);
  vector[J] b = inv_logit(logit_ab[ : , 2]);
}
model {
  vector[J * T] p_flat;

  mu_logit_ab ~ logistic(0, 1);
  sigma_logit_ab ~ normal(0, 1);
  L_logit_ab ~ lkj_corr_cholesky(2);
  z ~ normal(0, 1);

  for (j in 1 : J) {
    for (t in 1 : T) {
      p_flat[(j - 1) * T + t] = a[j] ^ prev_shock[j, t] * b[j] ^ prev_avoid[j, t];
    }
  }
  y_flat ~ bernoulli(p_flat);
}
generated quantities {
  array[J, T] int<lower=0, upper=1> y_rep;
  {
    real prev_shock_rep;
    real prev_avoid_rep;
    real p_rep;
    for (j in 1 : J) {
      prev_shock_rep = 0;
      prev_avoid_rep = 0;
      y_rep[j, 1] = 1;
      for (t in 2 : T) {
        prev_shock_rep = prev_shock_rep + y_rep[j, t - 1];
        prev_avoid_rep = prev_avoid_rep + 1 - y_rep[j, t - 1];
        p_rep = a[j] ^ prev_shock_rep * b[j] ^ prev_avoid_rep;
        y_rep[j, t] = bernoulli_rng(p_rep);
      }
    }
  }
}
","data_safe_json":"{"n_dogs":2,"n_trials":3,"y":[[0,0,1],[0,0,0]],"y_flat":[0,0,1,0,0,0]}","protected_variables":["y_flat"]}
